// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import type { Meta, StoryObj } from '@storybook/preact-vite';
import {
  RadioButton,
  RadioButtonProps,
} from '@adobe-commerce/elsie/components/RadioButton';
import { expect, userEvent, within } from 'storybook/test';
import { IconsList } from '@adobe-commerce/elsie/components/Icon/Icon.stories.helpers';

/**
 * Use Radio Buttons to let users select one option from a set of mutually exclusive choices.
 */
const meta: Meta<RadioButtonProps> = {
  title: 'Components/RadioButton',
  component: RadioButton,
  argTypes: {
    label: {
      description: 'Label to be shown beside of the radio button',
      type: {
        required: true,
        name: 'string',
      },
    },
    name: {
      description: 'Field name (used for mapping the value in a form)',
      type: {
        required: true,
        name: 'string',
      },
    },
    value: {
      description: 'Field value',
      type: {
        required: true,
        name: 'string',
      },
    },
    description: {
      description: 'Additional secondary description if needed',
      type: {
        required: false,
        name: 'string',
      },
    },
    disabled: {
      description: 'Whether or not the radio button is disabled',
      type: {
        required: false,
        name: 'boolean',
      },
    },
    error: {
      description: 'Whether or not the radio button is in error state',
      type: {
        required: false,
        name: 'boolean',
      },
    },
    size: {
      description:
        'Available sizes for the checkbox label and description texts',
      type: 'string',
      options: ['medium', 'large'],
      defaultValue: {
        summary: 'medium',
      },
      control: {
        type: 'radio',
        default: 'medium',
      },
    },
    checked: {
      description: 'Whether or not the radio button is checked',
      type: {
        required: false,
        name: 'boolean',
      },
    },
    busy: {
      description: 'Whether or not the radio button is busy',
      type: {
        required: false,
        name: 'boolean',
      },
    },
    icon: {
      description:
        'Optional icon to display before the label (SVG or img element)',
      options: Object.keys(IconsList),
      mapping: IconsList,
      control: {
        type: 'select',
      },
    },
  },
};

export default meta;

type Story = StoryObj<RadioButtonProps>;

/**
 * ```ts
 * import { RadioButton } from '@adobe-commerce/elsie/components/RadioButton';
 * ```
 */

export const RadioButtonStory: Story = {
  name: 'Radio button',
  args: {
    name: 'standard',
    label: 'Standard',
    value: 'standard',
    description: 'Description',
    size: 'medium',
    disabled: false,
    error: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const radioButton = await canvas.findByRole('radio');
    const radioButtonText = await canvas.findByText('Standard');
    await expect(radioButton).not.toBeChecked();
    await userEvent.click(radioButtonText);
    await expect(radioButton).toBeChecked();
  },
};

export const RadioButtonWithIcon: Story = {
  name: 'Radio button with icon',
  args: {
    name: 'shipping',
    label: 'Free Shipping',
    value: 'free-shipping',
    description: 'Delivery in 5-7 business days',
    size: 'medium',
    disabled: false,
    error: false,
    // @ts-ignore - icon is mapped from IconsList
    icon: 'Delivery',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const radioButton = await canvas.findByRole('radio');
    const radioButtonContainer = radioButton.closest('.dropin-radio-button');
    const icon = radioButtonContainer?.querySelector(
      '.dropin-radio-button__icon'
    );
    await expect(icon).toBeInTheDocument();
  },
};
